//! Leader check for T41a: 418 statements compared with sqlite3 3.53 (STRICT tables),
//! generated by briefs/leader/gen_sql_cases.py into sql_cases.txt, plus encoding properties.
#![allow(clippy::unwrap_used, clippy::panic, clippy::cast_possible_truncation)]
use assay::Rng;
use iridium::sql::{decode_record, encode_key, encode_record, Db, Value};
use iridium::{Error, MemStorage};
use std::cmp::Ordering;

const CASES: &str = include_str!("sql_cases.txt");

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn enc(v: &Value) -> String {
    match v {
        Value::Null => "N".into(),
        Value::Int(i) => format!("I{i}"),
        Value::Text(t) => format!("T{}", assay::to_hex(t.as_bytes())),
        Value::Blob(b) => format!("B{}", assay::to_hex(b)),
    }
}

fn kind_ok(kind: &str, e: &Error) -> bool {
    match kind {
        "ConstraintNN" => matches!(e, Error::Constraint(m) if m.contains("NOT NULL")),
        "ConstraintU" => matches!(e, Error::Constraint(m) if m.contains("UNIQUE")),
        "Type" => matches!(e, Error::Type),
        "NoSuchTable" => matches!(e, Error::NoSuchTable),
        "NoSuchIndex" => matches!(e, Error::NoSuchTable | Error::NoSuchColumn),
        "NoSuchColumn" => matches!(e, Error::NoSuchColumn),
        "Exists" => matches!(e, Error::Exists),
        "Misuse" => matches!(e, Error::Misuse),
        "Overflow" => matches!(e, Error::Overflow),
        "Parse" => matches!(e, Error::Parse { .. }),
        _ => true,
    }
}

#[test]
fn matches_sqlite() {
    let mut lines = CASES.lines().peekable();
    let mut db: Option<Db<MemStorage>> = None;
    let (mut n, mut fails) = (0, Vec::new());
    while let Some(l) = lines.next() {
        if l == "NEW" {
            db = Some(Db::open(MemStorage::new(), MemStorage::new()).unwrap());
            continue;
        }
        if l == "REOPEN" {
            let (m, g) = db.take().unwrap().close().unwrap();
            db = Some(Db::open(m, g).unwrap());
            continue;
        }
        let sql = String::from_utf8(unhex(&l[2..])).unwrap();
        n += 1;
        let want = lines.next().unwrap();
        let got = db.as_mut().unwrap().execute(&sql);
        if let Some(kind) = want.strip_prefix("E ") {
            match &got {
                Err(e) if kind_ok(kind, e) => {}
                other => fails.push(format!("{sql}\n  want error {kind}, got {other:?}")),
            }
            continue;
        }
        let f: Vec<&str> = want.split(' ').collect();
        let (changes, ordered, nrows): (u64, bool, usize) =
            (f[1].parse().unwrap(), f[2] == "1", f[3].parse().unwrap());
        let cols: Vec<String> = f
            .get(4)
            .filter(|c| !c.is_empty())
            .map(|c| {
                c.split(',')
                    .map(|h| String::from_utf8(unhex(h)).unwrap())
                    .collect()
            })
            .unwrap_or_default();
        let mut want_rows: Vec<String> = (0..nrows)
            .map(|_| lines.next().unwrap()[2..].to_string())
            .collect();
        let rows = match got {
            Ok(r) => r,
            Err(e) => {
                fails.push(format!("{sql}\n  want ok, got {e:?}"));
                continue;
            }
        };
        let mut got_rows: Vec<String> = rows
            .rows
            .iter()
            .map(|r| r.iter().map(enc).collect::<Vec<_>>().join(","))
            .collect();
        if !ordered {
            want_rows.sort();
            got_rows.sort();
        }
        if sql.starts_with("SELECT") && rows.columns != cols {
            fails.push(format!(
                "{sql}\n  columns want {cols:?} got {:?}",
                rows.columns
            ));
        }
        if rows.changes != changes {
            fails.push(format!(
                "{sql}\n  changes want {changes} got {}",
                rows.changes
            ));
        }
        if got_rows != want_rows {
            fails.push(format!(
                "{sql}\n  rows want {want_rows:?}\n  got {got_rows:?}"
            ));
        }
    }
    assert!(n >= 300, "only {n} statements");
    assert!(
        fails.is_empty(),
        "{} of {n} statements differ:\n{}",
        fails.len(),
        fails[..fails.len().min(8)].join("\n")
    );
}

fn rand_value(r: &mut Rng) -> Value {
    match r.below(4) {
        0 => Value::Null,
        1 => Value::Int(
            *r.pick(&[i64::MIN, i64::MAX, 0, -1, 1, 255, 256, -256]) ^ (r.below(3) as i64),
        ),
        2 => Value::Text(String::from_utf8_lossy(&r.bytes(6)).into_owned()),
        _ => Value::Blob(r.bytes(6)),
    }
}

/// SQLite order: NULL < INTEGER < TEXT < BLOB; text and blobs bytewise.
fn sql_cmp(a: &Value, b: &Value) -> Ordering {
    let rank = |v: &Value| match v {
        Value::Null => 0,
        Value::Int(_) => 1,
        Value::Text(_) => 2,
        Value::Blob(_) => 3,
    };
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Text(x), Value::Text(y)) => x.as_bytes().cmp(y.as_bytes()),
        (Value::Blob(x), Value::Blob(y)) => x.cmp(y),
        _ => rank(a).cmp(&rank(b)),
    }
}

#[test]
fn key_order_and_record_round_trip() {
    let mut r = Rng::new(0x41A_0001);
    for _ in 0..5000 {
        let n = 1 + r.below(3);
        let a: Vec<Value> = (0..n).map(|_| rand_value(&mut r)).collect();
        let mut b: Vec<Value> = (0..n).map(|_| rand_value(&mut r)).collect();
        if r.chance(1, 3) {
            b[..n - 1].clone_from_slice(&a[..n - 1]);
        }
        let want = a
            .iter()
            .zip(&b)
            .map(|(x, y)| sql_cmp(x, y))
            .find(|o| o.is_ne())
            .unwrap_or(Ordering::Equal);
        assert_eq!(encode_key(&a).cmp(&encode_key(&b)), want, "{a:?} vs {b:?}");
        assert_eq!(decode_record(&encode_record(&a)).unwrap(), a);
    }
}

#[test]
fn hostile_input_never_panics() {
    let mut r = Rng::new(0x41A_0002);
    for _ in 0..20_000 {
        let _ = decode_record(&r.bytes(40));
    }
    let mut good = encode_record(&[
        Value::Int(5),
        Value::Text("abc".into()),
        Value::Blob(vec![1, 2]),
    ]);
    for _ in 0..5000 {
        let i = r.below(good.len());
        good[i] ^= 1 << r.below(8);
        let _ = decode_record(&good);
    }
    let toks = [
        "SELECT",
        "FROM",
        "t",
        "(",
        ")",
        ",",
        "'",
        "x'",
        "WHERE",
        "a",
        "=",
        "1",
        "NULL",
        "*",
        "||",
        "-",
        "9223372036854775807",
        "CASE",
        "WHEN",
        "END",
        "GROUP",
        "BY",
        "ORDER",
        "LIMIT",
        "INSERT",
        "INTO",
        "VALUES",
        "UPDATE",
        "SET",
        "DELETE",
        "CREATE",
        "TABLE",
        "INDEX",
        "ON",
        "DROP",
        "BEGIN",
        "COMMIT",
        "ROLLBACK",
        "JOIN",
        "EXPLAIN",
        "LIKE",
        "IN",
        "BETWEEN",
        "AND",
        "NOT",
        "IS",
        "substr",
        "count",
        ";",
        "\u{e9}",
        "\0",
    ];
    let mut db = Db::open(MemStorage::new(), MemStorage::new()).unwrap();
    db.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, a INTEGER, b TEXT)")
        .unwrap();
    db.execute("INSERT INTO t (a, b) VALUES (1, 'x'), (NULL, 'y'), (3, NULL)")
        .unwrap();
    for _ in 0..20_000 {
        let s: Vec<&str> = (0..1 + r.below(12)).map(|_| *r.pick(&toks)).collect();
        let _ = db.execute(&s.join(" "));
    }
    assert!(db.close().is_ok(), "close after fuzz");
}
